{
    "id": "vuln-logkitty-ef2f673e",
    "message": "Use of execSync with string concatenation creates potential command injection vulnerability. The vulnerable code constructs shell commands by concatenating user-provided variables directly into the command string, which can allow attackers to inject malicious commands. The fix uses execFileSync with an array of arguments instead, which properly separates command arguments and prevents shell injection. This pattern should be replaced throughout the codebase to prevent similar vulnerabilities.",
    "severity": "ERROR",
    "languages": ["typescript"],
    "metadata": {
        "category": "security",
        "cwe": "78",
        "owasp": "OWASP Top 10:2021 - A03:2021 - Injection"
    },
    "pattern_either": [
        "execSync(`${...} ...`)",
        "execSync('...' + ...)",
        "execSync(`...${...}...`)"
    ],
    "pattern_not": [
        "execFileSync(..., [...])",
        "execFileSync(..., [\"...\"])"
    ]
}

